use super::*;

/// 🧩️ Concave, smooth, flipped and shared-edge source polygons use the same funded normal cursor and retain original asset allocations.
#[test]
fn original_mesh_tessellation_normal_polygons_keep_original_assets(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{retained_clone::RetainedCloneGrant,retirement::controlled::{ControlledRetirement,ErasedControlledRetirement},DslValue};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();let assets=&law["surfaceAssetCustody"];
    for polygon in law["polygons"].as_array().unwrap(){for close_copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
        let(mut job,source)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(polygon["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(polygon["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();for face in&mut mesh.faces{face.smooth=polygon["smooth"].as_bool().unwrap();face.flipped=polygon["flipped"].as_bool().unwrap();}let mut materials=HistoryFoldIndex::new();materials.insert(assets["materialKey"].as_str().unwrap().to_owned(),DslValue::from(assets["material"].clone()));let mut textures=HistoryFoldIndex::new();textures.insert(assets["textureKey"].as_str().unwrap().to_owned(),MeshTexture {mime:assets["texture"]["mime"].as_str().unwrap().to_owned(),bytes:serde_json::from_value(assets["texture"]["bytes"].clone()).unwrap()});mesh.set_surface_assets(materials,textures).unwrap();MeshTessellationJob::new(mesh)});
        let original=job.mesh.vertices.as_ptr();let material=job.mesh.materials.get_key_value(assets["materialKey"].as_str().unwrap()).unwrap();let material_pointer=(material.0.as_ptr(),material.1.as_object().unwrap().as_ptr());let texture=job.mesh.textures.get_key_value(assets["textureKey"].as_str().unwrap()).unwrap();let texture_pointer=(texture.0.as_ptr(),texture.1.mime.as_ptr(),texture.1.bytes.as_ptr());let(mut born,mut freed,mut turns)=(source.0,source.1,0);
        let output=loop{let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:128,maximum_capacity_bytes:job.next_normal_capacity_byte_demand(128).unwrap(),maximum_release_bytes:job.next_normal_release_byte_demand().unwrap(),maximum_depth:job.next_normal_depth_demand().unwrap()};let((step,receipt),heap)=observe(||job.step(grant).unwrap());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(receipt,job.normal_step_progress());assert!(receipt.fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000,"original polygon {} stalled",polygon["id"]);assert_eq!(job.mesh.vertices.as_ptr(),original);if let MeshTessellationStep::Done(output)=step{break output;}};
        assert_eq!(output.indices.len()/3,polygon["triangles"].as_u64().unwrap()as usize);let area=output.indices.chunks_exact(3).map(|triangle|{let point=|index:u32|{let offset=index as usize*3;[output.positions[offset]as f64,output.positions[offset+1]as f64]};let[a,b,c]=[triangle[0],triangle[1],triangle[2]].map(point);((b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])).abs()/2.0}).sum::<f64>();assert_eq!(area,polygon["area"].as_f64().unwrap());for normal in output.normals.chunks_exact(3){assert_eq!(normal,[0.0,0.0,polygon["normalZ"].as_f64().unwrap()as f32]);}
        let material=output.materials.get_key_value(assets["materialKey"].as_str().unwrap()).unwrap();assert_eq!((material.0.as_ptr(),material.1.as_object().unwrap().as_ptr()),material_pointer);let texture=output.textures.get_key_value(assets["textureKey"].as_str().unwrap()).unwrap();assert_eq!((texture.0.as_ptr(),texture.1.mime.as_ptr(),texture.1.bytes.as_ptr()),texture_pointer);assert_eq!(texture.1.bytes,serde_json::from_value::<Vec<u8>>(assets["texture"]["bytes"].clone()).unwrap());assert!(job.mesh.materials.terminal_is_empty()&&job.mesh.textures.terminal_is_empty());
        let(mut job_owner,handoff)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original polygon Job closure unsupported")));assert_eq!(handoff,(0,0));let(mut output_owner,handoff)=observe(||ControlledRetirement::new(output).unwrap_or_else(|_|panic!("original polygon output closure unsupported")));assert_eq!(handoff,(0,0));for owner in[&mut job_owner as&mut dyn ErasedControlledRetirement,&mut output_owner]{while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:close_copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(close_copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}}
        assert_eq!(born,freed);let(_,heap)=observe(||{drop(job_owner);drop(output_owner);});assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh normal polygon={} closeCopy={close_copy} actualArea={area} sameSource=true sameOriginalAssetPayload=true physical={freed} terminalDrop=0",polygon["id"].as_str().unwrap());
    }}
}
